def design(xy):
 x,y=np.asarray(xy).T/1000
 return np.array([np.ones(len(x)),x,y,x*x,x*y,y*y]).T

def distances(a,b):
 lat=np.radians((a[:,1]+b[:,1])/2)
 return np.sqrt(((a[:,0]-b[:,0])*111.32*np.cos(lat))**2+((a[:,1]-b[:,1])*111.32)**2)
for s in SHEETS.values():
 c=s['controls']; xy=np.array([[r[1],r[2]] for r in c]); ll=np.array([[r[3],r[4]] for r in c]); a=design(xy)
 coef=np.linalg.lstsq(a,ll,rcond=None)[0]; pred=a@coef
 held=[]
 for i in range(len(c)):
  keep=np.arange(len(c))!=i
  held.append(a[i]@np.linalg.lstsq(a[keep],ll[keep],rcond=None)[0])
 s['coefficients']=coef.tolist();s['rmseKm']=float(np.sqrt(np.mean(distances(pred,ll)**2)));s['loocvRMSEKm']=float(np.sqrt(np.mean(distances(np.array(held),ll)**2)));s['maxLOOCVErrorKm']=float(max(distances(np.array(held),ll)))
FEATURES=[]
def add(sheet,id,name,family,branch,cluster,subcluster,pts,level='片',note='',parent=None):
 s=SHEETS[sheet]; coords=(design(pts)@np.array(s['coefficients'])).round(6).tolist();coords.append(coords[0]);scale=s['size'][0]/1800
 FEATURES.append({'type':'Feature','properties':{'id':id,'name':name,'family':family,'branch':branch,'cluster':cluster,'subcluster':subcluster,'level':level,'source':s.get('source',sheet),'insetId':sheet if '-' in sheet else None,'registrationFrame':sheet,'parentId':parent,'method':'manual-source-pixel-tracing; quadratic-sheet-registration','reviewStatus':'approximate-traced','evidenceNote':note or '人工沿原图色块与片界概化描摹；并非实测互通边界。','sourceBoundary':[[round(x*scale,1),round(y*scale,1)] for x,y in pts],'sourceImageSize':s['size'],'registrationRMSEKm':round(s['loocvRMSEKm'],2),'registrationTrainingRMSEKm':round(s['rmseKm'],2),'partialCoverage':True,'coverageComplete':False,'registrationLOOCVKM':round(s['loocvRMSEKm'],2),'mutualIntelligibilityEvidence':'no-region-pair-measurement','boundaryPrecision':'regional-approximation'},'geometry':{'type':'Polygon','coordinates':[coords]}})

def add_parts(sheet,id,name,family,branch,cluster,subcluster,parts,level='片',note='',method='source-color-contours; manually-reviewed'):
 first=parts[0]; add(sheet,id,name,family,branch,cluster,subcluster,first['outer'],level,note)
 f=FEATURES[-1]; s=SHEETS[sheet];scale=s['size'][0]/1800;geoms=[];source_parts=[]
 for p in parts:
  rings=[]
  for ring in [p['outer']]+p.get('holes',[]):
   xy=(design(ring)@np.array(s['coefficients'])).round(6).tolist();xy.append(xy[0]);rings.append(xy)
  geoms.append(rings);source_parts.append({'outer':[[round(x*scale,1),round(y*scale,1)] for x,y in p['outer']],'holes':[[[round(x*scale,1),round(y*scale,1)] for x,y in h] for h in p.get('holes',[])]})
 f['geometry']={'type':'MultiPolygon','coordinates':geoms} if len(geoms)>1 else {'type':'Polygon','coordinates':geoms[0]}
 f['properties']['sourceParts']=source_parts;f['properties']['sourceHoles']=source_parts[0]['holes'];f['properties']['method']=method

